using AppCondominio.Modules.Reservations.Infrastructure;using Microsoft.Extensions.Diagnostics.HealthChecks;
namespace AppCondominio.Api.Health;public sealed class ReservationsDatabaseHealthCheck(ReservationsDbContext dbContext):IHealthCheck{public async Task<HealthCheckResult> CheckHealthAsync(HealthCheckContext context,CancellationToken cancellationToken=default){try{return await dbContext.Database.CanConnectAsync(cancellationToken)?HealthCheckResult.Healthy("Reservations SQL Server is reachable."):HealthCheckResult.Unhealthy("Reservations SQL Server is not reachable.");}catch(Exception ex){return HealthCheckResult.Unhealthy("Reservations SQL Server readiness check failed.",ex);}}}